select jsonb_build_object('login_enabled',(select login_enabled from operational.auth_gate where id=true),'credential_anon_select',has_column_privilege('anon','public."paswordTbl"','PasswordHas','SELECT'),'credential_policies',(select jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'cmd',cmd,'qual',qual)) from pg_policies where schemaname='public' and tablename='paswordTbl')) as audit;
